drop policy if exists assignment_submission_update on public.assignment_submissions;
create policy assignment_submission_update on public.assignment_submissions for update to authenticated using((student_id=auth.uid() and score is null and public.student_can_submit(assignment_id)) or public.can_manage_assignment(assignment_id)) with check((student_id=auth.uid() and score is null and public.student_can_submit(assignment_id)) or public.can_manage_assignment(assignment_id));
create or replace function public.guard_student_submission_state() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$ begin if auth.uid() is null or public.current_app_role()<>'STUDENT' then return new; end if; if tg_table_name='assessment_attempts' and tg_op='UPDATE' then if old.student_id<>auth.uid() or old.status<>'IN_PROGRESS' then raise exception 'Submitted attempt is locked'; end if; if new.started_at is distinct from old.started_at or new.submitted_at is distinct from old.submitted_at and new.status<>'SUBMITTED' then raise exception 'Attempt timestamps cannot be changed'; end if; if new.status='SUBMITTED' and new.submitted_at is null then new.submitted_at=now(); end if; end if; if tg_table_name='assignment_submissions' and tg_op='UPDATE' then if old.student_id<>auth.uid() or new.status is distinct from old.status or new.submitted_at is distinct from old.submitted_at or new.graded_at is distinct from old.graded_at or new.graded_by is distinct from old.graded_by then raise exception 'Submission state and timestamps cannot be changed by students'; end if; if new.text_content is distinct from old.text_content or new.storage_path is distinct from old.storage_path then new.is_edited=true; end if; end if; return new; end $$;
create trigger guard_student_attempt_update before update on public.assessment_attempts for each row execute function public.guard_student_submission_state();
create trigger guard_student_assignment_update before update on public.assignment_submissions for each row execute function public.guard_student_submission_state();
